  <script>
    (function () {
      var section = document.getElementById("about");
      if (!section) return;
      section.classList.add("has-js");

      var card = section.querySelector(".carousel");
      var slides = section.querySelectorAll(".carousel-slide");
      var dots = section.querySelectorAll(".carousel-dot");
      var prev = section.querySelector(".carousel-prev");
      var next = section.querySelector(".carousel-next");
      var index = 0;
      var timer = null;
      var DELAY = 5000;
      var reduceMotion = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

      function show(n) {
        index = (n + slides.length) % slides.length;
        slides.forEach(function (slide, i) {
          slide.classList.toggle("is-active", i === index);
        });
        dots.forEach(function (dot, i) {
          dot.classList.toggle("is-active", i === index);
        });
      }

      function stop() {
        if (timer) {
          clearInterval(timer);
          timer = null;
        }
      }

      function start() {
        stop();
        if (reduceMotion) return;
        timer = setInterval(function () { show(index + 1); }, DELAY);
      }

      function go(n) {
        show(n);
        start();
      }

      prev.addEventListener("click", function () { go(index - 1); });
      next.addEventListener("click", function () { go(index + 1); });
      dots.forEach(function (dot, i) {
        dot.addEventListener("click", function () { go(i); });
      });

      card.addEventListener("mouseenter", stop);
      card.addEventListener("mouseleave", start);
      card.addEventListener("focusin", stop);
      card.addEventListener("focusout", start);

      show(0);
      start();
    })();
  </script>
